Step 3 — Update dashboard/app/lib/contexts/CompanyContext.tsx to be a thin compatibility shim. Replace the entire file contents with:
  'use client';
  export { OrganizationProvider as CompanyProvider, useOrganization as useCompany } from './OrganizationContext';
  // Legacy type alias for pages that import Company
  export type { OrgContextValue as CompanyContextValue } from './OrganizationContext';
  This keeps all existing `import { useCompany } from './CompanyContext'` and `CompanyProvider` usages working without any changes in consuming files.
